insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('CM', 'CM-P-1925', 'Achats de biens 17,5 % + CAC (19,25 % déductible)', '{}'::jsonb, 'Le CAC communal est inclus dans le taux affiché et déductible comme la TVA elle-même — le pack ne le distingue pas sur les achats, faute de compte de TVA récupérable propre au CAC dans le plan SYSCOHADA (voir README). rate porte le taux affiché de 19,25 % en un seul posting (factor 100 par défaut), pour éviter le même double arrondi qu''un principal à 17,5 % majoré d''un factor 110 aurait introduit.', 'percent', 19.25, 'purchase', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 143 — la TVA est déductible dès lors qu''elle figure sur une facture délivrée à travers le système de suivi de facturation électronique de l''administration fiscale, par un fournisseur immatriculé, actif et au réel (art. 143 (1) b)) ; art. 142 pour le taux ; Livre de fiscalité locale art. C 82/C 83 — les centimes additionnels communaux, inclus au taux affiché de 19,25 %, sont déductibles comme la taxe elle-même (choix national confirmé par la fiche TVA de la DGI)', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CM', 'CM-P-1925-IMMO', 'Immobilisations 17,5 % + CAC (19,25 % déductible)', '{}'::jsonb, null, 'percent', 19.25, 'purchase', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 143, comme CM-P-1925', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CM', 'CM-P-1925-SRV', 'Services extérieurs 17,5 % + CAC (19,25 % déductible)', '{}'::jsonb, null, 'percent', 19.25, 'purchase', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 143, comme CM-P-1925', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CM', 'CM-S-10', 'Vente de logement social 10 % (taux réduit, LF 2026)', '{}'::jsonb, 'Vente d''un logement social à une personne physique pour sa première maison d''habitation, quitus fiscal — taux réduit sans CAC identifié', 'percent', 10, 'sale', 'domestic', date '2026-01-01', null, 'Code général des impôts, art. 142 (1) a) et (3), dans la rédaction de la loi de finances pour 2026 — taux réduit de 10 % sur la vente de logements sociaux aux personnes physiques pour l''acquisition de leur première maison d''habitation, sous quitus fiscal (remplace l''exonération antérieure de l''art. 128 (18)-(19)) ; circulaire n° 008/MINFI/DGI/LRI/L du 2 mars 2026, § 388-403 — applicable aux faits générateurs à compter du 1er janvier 2026, mention obligatoire « TVA au taux réduit de 10% - Article 142(3) du CGI » avec la nature de l''opération. Le taux réduit s''applique aussi aux intérêts des prêts immobiliers des personnes physiques et aux locations de logements sociaux par les promoteurs publics ou parapublics, deux opérations qu''aucun document de ce golden n''illustre.', 'S', null, 30, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CM', 'CM-S-1925', 'Ventes de biens 17,5 % + CAC 10 % (19,25 %)', '{}'::jsonb, 'Livraisons de biens au taux principal, majorées des centimes additionnels communaux ; TVA au compte 4431, CAC au compte 4422', 'percent', 19.25, 'sale', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 142 (1) a) — taux principal de 17,5 % sur la base hors taxe ; Livre de fiscalité locale, art. C 82 et C 83 (1) — centimes additionnels communaux (CAC) égaux à 10 % du principal de la TVA, soit un taux affiché de 19,25 % (art. 142 (2) et (3)). rate porte le taux affiché, celui que le client paie réellement (17,5 % × 1,10) ; les deux postings le répartissent en 90,909 % (= 17,5 / 19,25, soit 10/11) vers 4431 et 9,091 % (= 1,75 / 19,25, soit 1/11) vers 4422 — les trois décimales autorisées par factor_percent n''atteignent pas l''exactitude de 10/11, mais le posting du CAC, placé en dernier, absorbe l''écart de sorte que la somme des deux postings égale toujours exactement round(base × 19,25 %), donc ce que la facture porte. Un taux déclaré à 17,5 avec un second posting factor 10 (10 % du principal) revenait au même calcul légal mais doublait l''arrondi (round(round(base × 17,5 %) × 1,10) au lieu de round(base × 19,25 %)) et pouvait décaler l''écriture d''une unité — voir docs/international.md § From the OHADA packs. La date de début retenue est celle à partir de laquelle ce pack décrit des livres tenus selon le SYSCOHADA révisé, et non celle du taux, resté inchangé depuis au moins 2018 (PwC Worldwide Tax Summaries, 14/08/2026).', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CM', 'CM-S-1925-SRV', 'Prestations de services 17,5 % + CAC 10 % (19,25 %)', '{}'::jsonb, 'Prestations de services au taux principal, majorées des centimes additionnels communaux ; TVA au compte 4432, CAC au compte 4422', 'percent', 19.25, 'sale', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 142 (1) a) et Livre de fiscalité locale art. C 82/C 83 (1), comme CM-S-1925, même répartition 90,909 % / 9,091 % et même raison d''arrondi. Aucun article fixant un fait générateur propre aux prestations de services (encaissement, option pour les débits) n''a été identifié dans le CGI 2026 chargé pour cette fiche : cette taxe n''est donc pas déclarée cash_basis, faute de texte l''imposant.', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CM', 'CM-S-EXO', 'Opération exonérée (art. 128)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2018-01-01', null, 'Code général des impôts, art. 128 — liste des opérations exonérées, dont les biens de première nécessité de l''annexe I du titre II (art. 128, 6) ; art. 150 (5) — la facture porte la mention « Exonérée » par produit', 'E', null, 50, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'fiche-tva', null, null, null, null),
  ('CM', 'CM-S-EXP', 'Exportation taux zéro', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2018-01-01', null, 'Code général des impôts, art. 142 (4) — taux zéro sur les exportations de produits taxables', 'G', null, 40, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

