insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('CM', 'CM-TVA', 'Déclaration de taxe sur la valeur ajoutée', array['month']::declaration_period[], 'month'::declaration_period, date '2018-01-01', null, 'Code général des impôts, art. 152 (2) — déclaration mensuelle des opérations imposables au régime du réel ; art. 152 — le modèle de la déclaration est fourni par l''administration fiscale, dont le nom officiel et la numérotation des cases n''ont été trouvés dans aucune source officielle chargée pour cette fiche. Les cases ci-dessous suivent le contenu que les art. 142, 143 et 152 imposent de déclarer (base par taux, taxe exigible, déductions, solde), et non la numérotation de l''imprimé ; Harmony (teledeclaration-dgi.cm) est le portail de télédéclaration.', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, 'Code général des impôts, art. 152 — déclaration due dans les 15 jours du mois suivant celui au titre duquel les opérations ont été réalisées (fiche TVA de la DGI : « avant le 15 du mois qui suit »).', 'fiche-tva', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
