update country_defaults set
  numbering_gapless             = true,
  number_format                 = '{CODE}/{YYYY}/{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Code général des impôts, art. 150 (5) — la facture porte « un numéro unique de facture en séquence chronologique et continue ». Le texte impose l''unicité et la continuité de la séquence, jamais une forme précise ni une remise à zéro annuelle, que le format proposé ici permet sans l''exiger.',
  numbering_source_key          = 'cgi',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Aucun article fixant le fait générateur et l''exigibilité de la TVA (l''équivalent des art. 141-142 d''autres codes de la zone) n''a été identifié dans le CGI 2026 chargé pour cette fiche : le texte lu couvre le taux (art. 142), la déduction (art. 143) et les mentions de facture (art. 150), jamais la date d''exigibilité elle-même. invoice_if_issued est retenu par défaut, par cohérence avec les autres packs OHADA (packs/sn, packs/ci) et parce qu''aucune taxe de ce pack n''est déclarée cash_basis faute de texte l''imposant — valeur à confirmer par un comptable local ou par lecture de l''article manquant.',
  tax_point_source_key          = 'cgi',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Code général des impôts, Livre des procédures fiscales, art. L 8 bis (1)-(2) — suivi électronique de la facturation par la DGI, dans les conditions fixées par arrêté du ministre en charge des finances, pour les secteurs et entreprises désignés (TIC, commerce en ligne, électricité, jeux, assurances, boissons, oléagineux, bouquets numériques, et toute entreprise de la Direction des grandes entreprises) ; art. 143 (1) b) — la TVA n''est déductible que si elle figure sur une facture délivrée à travers ce système par un fournisseur immatriculé, actif et au réel ; art. 8 bis (2), modifié par la loi n° 2024/13 du 23 décembre 2024 (loi de finances 2025) — une charge n''est déductible à l''IS que si sa facture est passée par ce système. Loi de finances 2026, Livre des procédures fiscales art. L 8 sexies nouveau — taxation en temps réel pour certaines opérations, équipements ou logiciels agréés, factures électroniques, transmission continue, modalités renvoyées à un arrêté (circulaire n° 008/MINFI/DGI/LRI/L du 2 mars 2026, § 507-511). Aucun arrêté d''application n''est publié à la date de ce pack ; aucun profil, aucune date de généralisation et aucun schéma de facture électronique n''ont été identifiés dans un texte officiel : profile et mandatory_from restent vides. Ekwo ne génère, ne transmet et ne certifie aucune facture par ce système.',
  einvoice_source_key           = 'cgi',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'CM';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('CM', 'exempt', 'exempt', 'Opération exonérée de la taxe sur la valeur ajoutée — article 128 du Code général des impôts.', '{}'::jsonb, 10, date '1970-01-01', null, 'Code général des impôts, art. 150 (5) — pour une opération exonérée, la facture porte une mention « Exonérée » ; art. 128 pour la liste des opérations exonérées'),
  ('CM', 'export', 'export', 'Exportation exonérée de la taxe sur la valeur ajoutée au taux zéro — article 142 (4) du Code général des impôts.', '{}'::jsonb, 20, date '1970-01-01', null, 'Code général des impôts, art. 150 (5) et art. 142 (4)')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
